sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // MSSCOLATRL-110

    // Add your code here
    try {

        updateUserManagingLocations(current);

    } catch (e) {
        gs.error(`Error in Business Rule Update 'Associated Managing Locations' :` + e.message);
    }

    function updateUserManagingLocations(grMember) {

        var userSysId = grMember.user.toString();

        // Get all groups for the user
        var gmGR = new GlideRecord('sys_user_grmember');
        gmGR.addQuery('user', userSysId);
        gmGR.query();

        // fetch the region from all the groups name which user is part of
        var regionList = new Set();
        while (gmGR.next()) {


            if (gmGR.group.name.toLowerCase().includes('read-only-non-seg')) {
                regionList.add('gsc');
            } else {
                var group = gmGR.group.name.toString().toLowerCase();
                var parts = group.split('-');

                regionList.add(parts[parts.length - 1]);
            }


        }


        // Fetch matching managing locations based on region checkboxes

        var locationSet = new Set();
        var regionField = Array.from(regionList);


        var locGR = new GlideRecord('x_hsb11_mss_coll_0_collateral_access_reference');
        locGR.query();

        // loop through all the managing location for each region stored regionList[] and 
        // if the checkbox is true for respective region then add the managing location to the locationSet set
        // set() does not contain any duplicate value so locationSet will have combination of managing location

        while (locGR.next()) {
            for (var i = 0; i < regionField.length; i++) {
                if (locGR.getValue(regionField[i]) === '1') {
                    var loc = locGR.scp_managing_location;
                    if (loc)
                        locationSet.add(loc.toString());
                }
            }
        }

        // set the field value in user table

        var userGR = new GlideRecord('sys_user');
        if (userGR.get(grMember.user)) {
            userGR.u_associated_managing_locations = Array.from(locationSet).join(',');
            userGR.update();
        }

    }



})(current, previous);
